j:jelly.script:
function useStaticValue(elementName) {
	var dynamicElement = gel('element.' + elementName + '.binding');
	dynamicElement.style.display = 'none';

	// If the JSON editor first rendered in a hidden state,
	// it needs to be refreshed to display correctly.
	var jsonElement = gel('cm.' + elementName);
	if (jsonElement) {
		jsonElement?.CodeMirror?.refresh();
	}

	var staticElement = gel('element.' + elementName);
	staticElement.style.display = 'block';

	onInputMapUseDynamic(elementName, false);
}
